"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["25422"],{89019(e){e.exports=JSON.parse('{"id":"FIN-580","slug":"contingent-liability","term":"Contingent Liability","also_known_as":[],"difficulty":"Intermediate","definition":"A contingent liability is a possible obligation that depends on the outcome of an uncertain future event, such as a lawsuit or a guarantee, and is not recorded on the balance sheet unless it becomes probable and measurable.","explanation":["Companies face many possible obligations that may never materialise. A customer might sue, a guarantee given for another company might be called, or a tax authority might challenge a past return. These are contingent liabilities.","Accounting treatment depends on likelihood. If payment is probable and can be estimated reliably, it is recorded as a provision. If it is possible but not probable, or cannot be reliably estimated, it is not recorded but must be disclosed in the notes. If the chance of payment is remote, it usually does not need to be disclosed at all.","For example, a company being sued for 5 million might, on legal advice, believe it is unlikely to lose. It would disclose the case in its notes as a contingent liability rather than recording a liability. If the case later turns against it, it would then record a provision.","Contingent liabilities matter to investors because they can turn into large costs. Reading the notes to the financial statements is the main way to find them, since they may not appear anywhere on the balance sheet."],"note":"","total":1500,"prev":{"slug":"contango","term":"Contango"},"next":{"slug":"continuous-compounding","term":"Continuous Compounding"}}')}}]);